CREATE SCHEMA IF NOT EXISTS "public";
CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"name" TEXT NOT NULL,"bio" TEXT NOT NULL DEFAULT '',"domain" TEXT NOT NULL DEFAULT '',"verificationStatus" TEXT NOT NULL DEFAULT 'UNVERIFIED',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Session" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"("id"),"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Capsule" ("id" TEXT PRIMARY KEY,"ownerId" TEXT NOT NULL REFERENCES "User"("id"),"title" TEXT NOT NULL,"slug" TEXT NOT NULL UNIQUE,"domain" TEXT NOT NULL,"scope" TEXT NOT NULL,"visibility" TEXT NOT NULL DEFAULT 'PRIVATE',"status" TEXT NOT NULL DEFAULT 'DRAFT',"currentVersion" TEXT,"revision" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "SourceAsset" ("id" TEXT PRIMARY KEY,"capsuleId" TEXT NOT NULL REFERENCES "Capsule"("id"),"contributorId" TEXT NOT NULL REFERENCES "User"("id"),"contributor" TEXT NOT NULL,"title" TEXT NOT NULL,"type" TEXT NOT NULL,"objectKey" TEXT NOT NULL UNIQUE,"sha256" TEXT NOT NULL,"contentType" TEXT NOT NULL,"size" INTEGER NOT NULL,"text" TEXT NOT NULL DEFAULT '',"status" TEXT NOT NULL DEFAULT 'PENDING',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "KnowledgeItem" ("id" TEXT PRIMARY KEY,"capsuleId" TEXT NOT NULL REFERENCES "Capsule"("id"),"sourceId" TEXT NOT NULL REFERENCES "SourceAsset"("id"),"contributorId" TEXT NOT NULL REFERENCES "User"("id"),"contributor" TEXT NOT NULL,"kind" TEXT NOT NULL,"text" TEXT NOT NULL,"proposal" TEXT NOT NULL,"confidence" DOUBLE PRECISION NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"critical" BOOLEAN NOT NULL DEFAULT false,"citation" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "CapsuleVersion" ("id" TEXT PRIMARY KEY,"capsuleId" TEXT NOT NULL REFERENCES "Capsule"("id"),"version" TEXT NOT NULL,"manifestHash" TEXT NOT NULL UNIQUE,"manifest" JSONB NOT NULL,"knowledge" JSONB NOT NULL,"evaluation" JSONB NOT NULL,"publishedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("capsuleId","version"));
CREATE TABLE "Evaluation" ("id" TEXT PRIMARY KEY,"capsuleId" TEXT NOT NULL REFERENCES "Capsule"("id"),"revision" INTEGER NOT NULL,"passed" BOOLEAN NOT NULL,"metrics" JSONB NOT NULL,"cases" JSONB NOT NULL,"suiteHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "EvaluationCase" ("id" TEXT PRIMARY KEY,"capsuleId" TEXT NOT NULL REFERENCES "Capsule"("id"),"question" TEXT NOT NULL,"expectedElements" TEXT[],"forbiddenElements" TEXT[],"unsupported" BOOLEAN NOT NULL DEFAULT false,"approvedBy" TEXT NOT NULL REFERENCES "User"("id"),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "LicenseTemplate" ("id" TEXT PRIMARY KEY,"capsuleId" TEXT NOT NULL REFERENCES "Capsule"("id"),"name" TEXT NOT NULL,"audience" TEXT NOT NULL,"purposes" TEXT[],"aiTrainingAllowed" BOOLEAN NOT NULL DEFAULT false,"commercialUse" BOOLEAN NOT NULL DEFAULT false,"derivativeUse" BOOLEAN NOT NULL DEFAULT false,"usageLimit" INTEGER NOT NULL,"durationDays" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "LicenseGrant" ("id" TEXT PRIMARY KEY,"templateId" TEXT NOT NULL REFERENCES "LicenseTemplate"("id"),"capsuleId" TEXT NOT NULL REFERENCES "Capsule"("id"),"ownerId" TEXT NOT NULL REFERENCES "User"("id"),"name" TEXT NOT NULL,"grantee" TEXT NOT NULL,"audience" TEXT NOT NULL,"purposes" TEXT[],"aiTrainingAllowed" BOOLEAN NOT NULL DEFAULT false,"commercialUse" BOOLEAN NOT NULL DEFAULT false,"derivativeUse" BOOLEAN NOT NULL DEFAULT false,"usageLimit" INTEGER NOT NULL,"used" INTEGER NOT NULL DEFAULT 0,"startsAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMP(3) NOT NULL,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK("used">=0 AND "used"<="usageLimit"));
CREATE TABLE "Conversation" ("id" TEXT PRIMARY KEY,"capsuleId" TEXT NOT NULL REFERENCES "Capsule"("id"),"userId" TEXT NOT NULL REFERENCES "User"("id"),"version" TEXT NOT NULL,"purpose" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Message" ("id" TEXT PRIMARY KEY,"conversationId" TEXT NOT NULL REFERENCES "Conversation"("id"),"userId" TEXT NOT NULL REFERENCES "User"("id"),"requestKey" TEXT NOT NULL UNIQUE,"question" TEXT NOT NULL,"answer" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "UsageEvent" ("id" TEXT PRIMARY KEY,"capsuleId" TEXT NOT NULL REFERENCES "Capsule"("id"),"capsuleVersionId" TEXT NOT NULL REFERENCES "CapsuleVersion"("id"),"licenseId" TEXT NOT NULL REFERENCES "LicenseGrant"("id"),"actorId" TEXT NOT NULL REFERENCES "User"("id"),"purpose" TEXT NOT NULL,"units" INTEGER NOT NULL DEFAULT 1,"requestKey" TEXT NOT NULL UNIQUE,"occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditEvent" ("id" TEXT PRIMARY KEY,"actorId" TEXT NOT NULL,"capsuleId" TEXT,"action" TEXT NOT NULL,"entityId" TEXT,"metadata" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Interview" ("id" TEXT PRIMARY KEY,"capsuleId" TEXT NOT NULL REFERENCES "Capsule"("id"),"ownerId" TEXT NOT NULL REFERENCES "User"("id"),"status" TEXT NOT NULL DEFAULT 'RECORDING',"coverage" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "InterviewSegment" ("id" TEXT PRIMARY KEY,"interviewId" TEXT NOT NULL REFERENCES "Interview"("id"),"sequence" INTEGER NOT NULL,"objectKey" TEXT NOT NULL,"sha256" TEXT NOT NULL,"text" TEXT NOT NULL DEFAULT '',UNIQUE("interviewId","sequence"));
CREATE TABLE "UploadTicket" ("id" TEXT PRIMARY KEY,"ownerId" TEXT NOT NULL REFERENCES "User"("id"),"capsuleId" TEXT NOT NULL REFERENCES "Capsule"("id"),"interviewId" TEXT,"sequence" INTEGER,"objectKey" TEXT NOT NULL UNIQUE,"contentType" TEXT NOT NULL,"size" INTEGER NOT NULL,"sha256" TEXT NOT NULL,"idempotencyKey" TEXT NOT NULL UNIQUE,"expiresAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "JobRecord" ("id" TEXT PRIMARY KEY,"capsuleId" TEXT NOT NULL,"kind" TEXT NOT NULL,"payload" JSONB NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"attempts" INTEGER NOT NULL DEFAULT 0,"lastError" TEXT,"result" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "AccessRequest" ("id" TEXT PRIMARY KEY,"capsuleId" TEXT NOT NULL REFERENCES "Capsule"("id"),"templateId" TEXT NOT NULL REFERENCES "LicenseTemplate"("id"),"userId" TEXT NOT NULL REFERENCES "User"("id"),"status" TEXT NOT NULL DEFAULT 'PENDING',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("templateId","userId"));
CREATE INDEX "Session_userId_idx" ON "Session"("userId");
CREATE INDEX "Capsule_ownerId_idx" ON "Capsule"("ownerId");
CREATE INDEX "Capsule_visibility_status_idx" ON "Capsule"("visibility","status");
CREATE INDEX "SourceAsset_capsuleId_idx" ON "SourceAsset"("capsuleId");
CREATE INDEX "KnowledgeItem_capsuleId_status_idx" ON "KnowledgeItem"("capsuleId","status");
CREATE INDEX "Evaluation_capsuleId_createdAt_idx" ON "Evaluation"("capsuleId","createdAt");
CREATE INDEX "EvaluationCase_capsuleId_idx" ON "EvaluationCase"("capsuleId");
CREATE INDEX "LicenseTemplate_capsuleId_idx" ON "LicenseTemplate"("capsuleId");
CREATE INDEX "LicenseGrant_capsuleId_grantee_status_idx" ON "LicenseGrant"("capsuleId","grantee","status");
CREATE INDEX "LicenseGrant_ownerId_idx" ON "LicenseGrant"("ownerId");
CREATE INDEX "UsageEvent_capsuleId_occurredAt_idx" ON "UsageEvent"("capsuleId","occurredAt");
CREATE INDEX "AuditEvent_capsuleId_createdAt_idx" ON "AuditEvent"("capsuleId","createdAt");
CREATE INDEX "JobRecord_status_kind_idx" ON "JobRecord"("status","kind");
CREATE FUNCTION reject_immutable_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Published records and audit history are immutable'; END; $$;
CREATE TRIGGER immutable_version BEFORE UPDATE OR DELETE ON "CapsuleVersion" FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON "AuditEvent" FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
